def hld(n={{n}}, tree={{tree}}, root={{root}}):
    parent = [-1]*n; depth = [0]*n; size = [1]*n; heavy = [-1]*n
    order = [root]; stack = [root]; parent[root] = -1
    while stack:
        u = stack.pop()
        for v in tree[u]:
            if v != parent[u]:
                parent[v] = u; depth[v] = depth[u]+1
                order.append(v); stack.append(v)
    for u in reversed(order):
        mx = 0
        for v in tree[u]:
            if v != parent[u]:
                size[u] += size[v]
                if size[v] > mx: mx = size[v]; heavy[u] = v
    head = list(range(n)); pos = [0]*n; cur = [0]
    def dfs(u, h):
        head[u] = h; pos[u] = cur[0]; cur[0] += 1
        if heavy[u] != -1: dfs(heavy[u], h)
        for v in tree[u]:
            if v != parent[u] and v != heavy[u]: dfs(v, v)
    dfs(root, root)
    return parent, depth, head, pos
